#!/usr/bin/env bash
# Generated by `verdant-studio publish` from studio/src/Studio/Ops.lex.tex. Do not edit.
# The one Lean export of the certified command. operate's propose-command and refresh both run it,
# and the studio check runs propose-command end to end, so a change that breaks it fails there.
# Export time is a requirement: every Lean phase runs under child_timeout_ms (300 s, studio/lexlean.toml),
# so this script measures each phase and fails at 240 s, 80 percent of that limit, before time can creep up to it.
set -euo pipefail
ll="$1"
log="$2"
phases="$log.phases"
: > "$phases.raw"
( while :; do ps -eo etimes=,args= | awk '$2 == "lean" && $3 == "-R" { m = $NF; sub(".*-src/", "", m); print $1, m }' >> "$phases.raw" || true; sleep 1; done ) &
watch=$!
status=0
(cd studio && "$ll" lock && "$ll" check && "$ll" production build --request production-request.json) > "$log" 2>&1 || status=$?
kill "$watch" 2> "$phases.err" || true
awk '{ if ($1 > t[$2]) t[$2] = $1 } END { for (m in t) print t[m], m }' "$phases.raw" | sort -rn > "$phases"
echo "Lean phases by wall time in seconds, longest first (the limit is 300, and the export fails at 240):"
head -n 8 "$phases"
if [ "$status" -ne 0 ]; then exit "$status"; fi
worst=$(head -n 1 "$phases" | cut -d ' ' -f 1)
if [ -n "$worst" ] && [ "$worst" -ge 240 ]; then
  echo "::error::a Lean phase took ${worst} s, within 20 percent of the 300 s limit: make its declarations cheaper to prove before adding more"
  exit 1
fi
rm -rf certified
cp -r studio/.lexlean/production/*/ certified
rm -f certified/packages/rust-std/verdant_studio/Cargo.lock
"$ll" production verify-artifact certified
